begin;
create table if not exists public.google_sheets_integrations(
 store_id uuid primary key references public.stores(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,spreadsheet_id text not null,spreadsheet_name text not null default 'Commandes Zelvora',encrypted_refresh_token text not null,status text not null default 'CONNECTED' check(status in('CONNECTED','ERROR','DISCONNECTED')),last_sync_at timestamptz,last_error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.google_sheets_integrations enable row level security;
drop policy if exists google_sheets_owner_read on public.google_sheets_integrations;create policy google_sheets_owner_read on public.google_sheets_integrations for select to authenticated using(user_id=auth.uid());
create or replace function public.get_store_dashboard_metrics(p_store_id uuid,p_since date default(current_date-29))returns jsonb language plpgsql stable security definer set search_path=public as $$declare result jsonb;begin if not public.can_access_store(p_store_id)then raise exception 'Accès refusé';end if;select jsonb_build_object('orders',count(*),'revenue',coalesce(sum(total)filter(where status<>'CANCELLED'),0),'averageOrder',coalesce(avg(total)filter(where status<>'CANCELLED'),0),'pending',count(*)filter(where status in('NEW','CONFIRMED','PREPARING','SHIPPED')),'delivered',count(*)filter(where status='DELIVERED'))into result from public.orders where store_id=p_store_id;return result||jsonb_build_object('visits',coalesce((select count(distinct session_id)from public.store_analytics_events where store_id=p_store_id and occurred_at>=p_since::timestamptz),0),'customers',(select count(*)from public.customers where store_id=p_store_id));end$$;grant execute on function public.get_store_dashboard_metrics(uuid,date)to authenticated;notify pgrst,'reload schema';commit;
